class Main {
    // 각 자리 숫자 중 가장 큰 숫자를 돌려줘요.
    static int maxDigit(int n) {
        // 지금까지 본 숫자 중 가장 큰 값이에요.
        int max = 0;
        while (n > 0) {
            // 맨 끝자리 숫자를 꺼내요.
            int digit = n % 10;
            // max를 고르는 자리예요.
            max = digit;
            // 끝자리를 지워요.
            n /= 10;
        }
        return max;
    }

    public static void main(String[] args) {
        // 가장 큰 숫자를 찾을 정수예요.
        int num = 5283;
        // 메서드에는 num의 값만 복사돼 넘어가요.
        System.out.println(num + "의 가장 큰 숫자: " + maxDigit(num));
    }
}
